--- Config/DefaultGame.ini ---
[/Script/EngineSettings.GeneralProjectSettings]
ProjectName=Pixel Arena
ProjectVersion=0.9.2

[/Script/UnrealEd.ProjectPackagingSettings]
Build=IfProjectHasCode
BuildConfiguration=PPBC_Shipping
UsePakFile=True
bCookAll=False
+MapsToCook=(FilePath="/Game/Maps/Arena")
+DirectoriesToAlwaysCook=(Path="/Game/Data/Effects")
; DA_Primary is loaded by path string in AArenaGameMode::BeginPlay, so the cook
; finds no reference to it from the map and would drop it from the pak.
+DirectoriesToAlwaysCook=(Path="/Game/Data/Palettes")
+DirectoriesToNeverCook=(Path="/Game/Dev")


--- Source/PixelArena/ArenaGameMode.h ---
#pragma once

#include "CoreMinimal.h"
#include "GameFramework/GameModeBase.h"
#include "ArenaGameMode.generated.h"

class UArenaHud;
class UArenaPalette;
class UArenaScoreTracker;
struct FArenaStats;

UCLASS()
class PIXELARENA_API AArenaGameMode : public AGameModeBase
{
	GENERATED_BODY()

public:
	virtual void BeginPlay() override;
	virtual void EndPlay(const EEndPlayReason::Type Reason) override;

	void OnGoalScored(int32 TeamIndex);

private:
	UPROPERTY()
	TObjectPtr<UArenaHud> Hud;

	UPROPERTY()
	TObjectPtr<UArenaPalette> Palette;

	// Must stay a UPROPERTY: created with NewObject and referenced only from
	// C++, so garbage collection would otherwise purge it mid-match and the
	// next OnGoalScored would dereference a stale pointer.
	UPROPERTY()
	TObjectPtr<UArenaScoreTracker> ScoreTracker = nullptr;

	// Plain C++ data owned by this class, freed in EndPlay.
	FArenaStats* Stats = nullptr;
};


--- result.json ---
{
  "crash_cause": "UArenaScoreTracker was created with NewObject in AArenaGameMode::BeginPlay but its member pointer in ArenaGameMode.h had no UPROPERTY() marker, so nothing in the object graph referenced it. Garbage collection purged it during the match (log line 'LogGarbage: Collecting garbage: 412 objects purged' at 21:05:13), leaving a dangling pointer. The next goal dereferenced the freed object: 'Goal for team 1' at 21:05:27 is immediately followed by 'EXCEPTION_ACCESS_VIOLATION reading address 0xffffffffffffffff' in UArenaScoreTracker::AddPoints() called from AArenaGameMode::OnGoalScored(). Fixed by marking ScoreTracker as UPROPERTY() (TObjectPtr) so the GameMode roots it for its whole lifetime.",
  "no_colors_cause": "The palette asset /Game/Data/Palettes/DA_Primary is never cooked into the packaged build. AArenaGameMode::BeginPlay loads it by path string with LoadObject, so the cook sees no hard reference from the cooked map, and Config/DefaultGame.ini had bCookAll=False plus DirectoriesToAlwaysCook only for /Game/Data/Effects, so /Game/Data/Palettes was left out of the pak. The log shows 'Couldn't find file for package /Game/Data/Palettes/DA_Primary', 'Failed to find object ArenaPalette ...' and 'Palette is null, using fallback gray', which is why the packaged arena renders gray while the editor (uncooked content, all assets available) shows colors. Fixed by adding +DirectoriesToAlwaysCook=(Path=\"/Game/Data/Palettes\") to Config/DefaultGame.ini."
}
